    "introduction": "쪽파와 여러 해산물, 반죽·달걀을 넣어 두툼하고 촉촉하게 부치는 부산 동래의 파전입니다. 동래장터 음식문화와 연결되며, 임금 진상이나 임진왜란 관련 이야기는 전승으로 구분합니다.",
