    "introduction": "고등어를 소금에 절여 보관·유통해 온 안동의 생선 운송·염장 문화에서 이어진 음식입니다. 주로 구이나 조림으로 밥과 먹으며, 일반 고등어구이와 구분해 간고등어 제품 사용 여부를 확인해야 합니다.",
