    "introduction": "따뜻한 콩국에 튀긴 반죽 등을 곁들여 먹는 대구의 간식입니다. 콩국 전문점과 야식 문화가 확인되지만 화교 전래의 구체적인 경로·시기는 명확하지 않으며, 부산 판매처는 이번 조사에서 확보하지 못했습니다.",
