    "sections": [
      "<dl class=\"info-card\"><div class=\"info-row\"><dt>분류</dt><dd>돼지고기 구이</dd></div><div class=\"info-row\"><dt>대표 지역</dt><dd>경북 청도 한재</dd></div><div class=\"info-row\"><dt>주재료</dt><dd>미나리 · 돼지삼겹살</dd></div><div class=\"info-row\"><dt>조리 방식</dt><dd>삼겹살과 미나리를 불판에서 구움</dd></div><div class=\"info-row\"><dt>맛·식감</dt><dd>기름진 고기와 아삭하고 향긋한 미나리</dd></div><div class=\"info-row\"><dt>매운맛</dt><dd>기본 낮음, 쌈장에 따라 다름</dd></div><div class=\"info-row\"><dt>계절</dt><dd>봄 중심, 하우스 재배·업소별 차이</dd></div><div class=\"info-row\"><dt>가격</dt><dd>식당별 메뉴 가격 참고</dd></div></dl>\n<h3>음식 소개·유래</h3>\n<p>향긋한 미나리와 삼겹살을 함께 구워 먹는 청도 한재미나리 산지의 음식문화입니다. 부산의 같은 이름 메뉴가 청도산 미나리를 사용한다고 단정할 수 없으므로 산지와 판매 시기를 확인해야 합니다.</p>\n<p>재료 변형: 돼지고기, 생미나리 제공 여부 확인</p>",
      "<p>보통 이렇게 즐깁니다. 양념·밥·곁들임은 개인 취향과 식당 제공 방식에 따라 달라집니다.</p>\n<ol class=\"steps\"><li><span>고기를 굽는 방식과 직원 조리 여부를 확인합니다. 직접 구울 때는 생고기용 집게와 먹는 도구를 구분합니다.</span></li><li><span>삼겹살을 충분히 익힙니다. 불판 가장자리나 고기 표면의 색만으로 안쪽 익힘을 단정하지 않습니다.</span></li><li><span>미나리는 가게 안내에 따라 익히거나 별도로 곁들입니다. 고기와 함께 먹기 좋은 길이로 준비합니다.</span></li><li><span>익은 고기와 미나리를 함께 먹습니다. 쌈장·소금·쌈채소는 취향에 따라 소량 곁들입니다.</span></li></ol>",
      "<ul><li><strong>일반적으로 확인할 재료:</strong> 돼지고기</li><li><strong>가게·메뉴별 가변 재료:</strong> 대두 · 밀 · 생선 · 새우</li></ul>\n<p>돼지고기를 우선 확인합니다. 쌈장·간장·양념과 곁들임의 대두·밀·새우·생선 성분은 별도로 확인하세요.</p>\n<ul><li><strong>생식·특수 재료:</strong> 돼지고기, 생미나리 제공 여부 확인</li><li><strong>채식:</strong> 일반 조리법은 동물성 재료 포함</li><li><strong>종교 식단:</strong> 원료·육수·양념·조리환경 및 필요한 인증 확인 필요</li></ul>\n<p>일반적인 조리법을 기준으로 한 안내입니다. 실제 재료·육수·소스와 공용 조리도구는 식당에 확인하세요. 미확인은 불포함이나 안전함을 뜻하지 않습니다.</p>",
      "<p>해당 메뉴 게시 자료 <strong>1곳</strong>, 유사 메뉴 자료 <strong>0곳</strong>. 현재 영업 직접 확인 <strong>0곳</strong>. 공개 전 재확인이 필요한 후보이며 추천 순위가 아닙니다.</p>\n<h3>해당 메뉴 게시 자료</h3>\n<h3>목구멍 하단점</h3>\n<ul><li><strong>주소:</strong> 부산 사하구 낙동대로450번길 12</li><li><strong>실제 메뉴 / 게시 가격:</strong> 청도 한재로 미나리 / 5,000원</li><li><strong>가격 기준:</strong> 게시 메뉴 표기 그대로. 중량·인분·최저가 여부 별도 확인. 현재 가격 미확인.</li><li><strong>게시 영업시간:</strong> 게시 요일 공통 16:30 - 02:00</li><li><strong>게시 정기휴무:</strong> 확인 필요</li><li><strong>외국인 방문 참고:</strong> 지점명·주소를 함께 제시. 외국어 메뉴·결제수단·최소주문·대기·휴무는 방문 전 문의.</li><li><strong>미확인:</strong> 현재 정상 영업 · 1인 방문 · 최소 주문량 · 외국어 메뉴 · 지도 장소·좌표 · 사진 이용 권한 · 실제 알레르기 성분</li><li><strong>지도 검색:</strong> <a href=\"https://map.naver.com/p/search/%EB%B6%80%EC%82%B0%20%EB%AA%A9%EA%B5%AC%EB%A9%8D%20%ED%95%98%EB%8B%A8%EC%A0%90%20%EB%B6%80%EC%82%B0%20%EC%82%AC%ED%95%98%EA%B5%AC%20%EB%82%99%EB%8F%99%EB%8C%80%EB%A1%9C450%EB%B2%88%EA%B8%B8%2012\" target=\"_blank\" rel=\"noopener noreferrer\">네이버 검색</a> / <a href=\"https://map.kakao.com/?q=%EB%B6%80%EC%82%B0%20%EB%AA%A9%EA%B5%AC%EB%A9%8D%20%ED%95%98%EB%8B%A8%EC%A0%90%20%EB%B6%80%EC%82%B0%20%EC%82%AC%ED%95%98%EA%B5%AC%20%EB%82%99%EB%8F%99%EB%8C%80%EB%A1%9C450%EB%B2%88%EA%B8%B8%2012\" target=\"_blank\" rel=\"noopener noreferrer\">카카오 검색</a> / <a href=\"https://www.google.com/maps/search/?api=1&amp;query=%EB%B6%80%EC%82%B0%20%EB%AA%A9%EA%B5%AC%EB%A9%8D%20%ED%95%98%EB%8B%A8%EC%A0%90%20%EB%B6%80%EC%82%B0%20%EC%82%AC%ED%95%98%EA%B5%AC%20%EB%82%99%EB%8F%99%EB%8C%80%EB%A1%9C450%EB%B2%88%EA%B8%B8%2012\" target=\"_blank\" rel=\"noopener noreferrer\">구글 검색</a></li><li><strong>조사일:</strong> 2026-11-03</li></ul>"
    ],
