        "html": "<ul><li><strong>주소:</strong> 부산 금정구 금정로149번길 13</li><li><strong>실제 메뉴 / 게시 가격:</strong> 대구막창 / 8,500원</li><li><strong>가격 기준:</strong> 게시 메뉴 표기 그대로. 중량·인분·최저가 여부 별도 확인. 현재 가격 미확인.</li><li><strong>게시 영업시간:</strong> 월요일 16:00 - 00:00 / 화요일 16:00 - 00:00 / 수요일 16:00 - 00:00 / 목요일 16:00 - 00:00 / 금요일 16:00 - 00:00 / 토요일 16:00 - 00:00 / 일요일 16:00 - 22:00</li><li><strong>게시 정기휴무:</strong> 확인 필요</li><li><strong>외국인 방문 참고:</strong> 지점명·주소를 함께 제시. 외국어 메뉴·결제수단·최소주문·대기·휴무는 방문 전 문의.</li><li><strong>미확인:</strong> 현재 정상 영업 · 1인 방문 · 최소 주문량 · 외국어 메뉴 · 지도 장소·좌표 · 사진 이용 권한 · 실제 알레르기 성분</li><li><strong>지도 검색:</strong> <a href=\"https://map.naver.com/p/search/%EB%B6%80%EC%82%B0%20%EC%84%B1%EC%95%A0%EB%AC%B8%ED%98%84%EA%B3%B1%EC%B0%BD%20%EB%B6%80%EC%82%B0%20%EA%B8%88%EC%A0%95%EA%B5%AC%20%EA%B8%88%EC%A0%95%EB%A1%9C149%EB%B2%88%EA%B8%B8%2013\" target=\"_blank\" rel=\"noopener noreferrer\">네이버 검색</a> / <a href=\"https://map.kakao.com/?q=%EB%B6%80%EC%82%B0%20%EC%84%B1%EC%95%A0%EB%AC%B8%ED%98%84%EA%B3%B1%EC%B0%BD%20%EB%B6%80%EC%82%B0%20%EA%B8%88%EC%A0%95%EA%B5%AC%20%EA%B8%88%EC%A0%95%EB%A1%9C149%EB%B2%88%EA%B8%B8%2013\" target=\"_blank\" rel=\"noopener noreferrer\">카카오 검색</a> / <a href=\"https://www.google.com/maps/search/?api=1&amp;query=%EB%B6%80%EC%82%B0%20%EC%84%B1%EC%95%A0%EB%AC%B8%ED%98%84%EA%B3%B1%EC%B0%BD%20%EB%B6%80%EC%82%B0%20%EA%B8%88%EC%A0%95%EA%B5%AC%20%EA%B8%88%EC%A0%95%EB%A1%9C149%EB%B2%88%EA%B8%B8%2013\" target=\"_blank\" rel=\"noopener noreferrer\">구글 검색</a></li><li><strong>조사일:</strong> 2026-11-03</li></ul>"
