    "introduction": "해양포유류인 고래를 부위별로 조리해 먹던 울산 장생포의 과거 포경산업과 연결된 식문화입니다. 이번 원고에서는 역사·문화 자료로 구분하며, 현행 규정·판매종·개별 유통 증빙을 검토하기 전까지 초기 서비스 추천과 먹는 방법 공개를 보류합니다.",
